    const P = []; for (let t = -PS_HALF; t <= PS_HALF + 0.01; t += PS_HALF/16) P.push(+t.toFixed(3));
    const hT = t => { const a = Math.abs(t); return a >= PS_MAIN ? 12 + 20*(PS_HALF - a)/(PS_HALF - PS_MAIN) : 14 + 18*Math.pow(a/PS_MAIN, 1.6); };
    for (const sg of [-1, 1]){
      const lf = t => cl(t) + sg*hw, yb = t => cz(t) - 2.4, yt = t => cz(t) - 2.4 + hT(t);
      truss(stl, P, lf, yb, yt, 'k', 0.55, 0.32);
      // main piers (concrete, to the water) and the end bents
      for (const tp of [-PS_MAIN, PS_MAIN]){ const gz = gnd(k, tp); bx(conc, tp - 4, tp + 4, gz <= -0.25 ? WAT : gz - 3, cz(tp) - 2.6, lf(tp) - 3, lf(tp) + 3); }
    }
    // top lateral struts and sway frames
    for (let i = 0; i < P.length; i += 2){ const t = P[i], y = cz(t) - 2.4 + hT(t); mb(sd, t, cl(t) - hw, y, t, cl(t) + hw, y, 0.3, 0.35); if (hT(t) > 15) mb(sd, t, cl(t) - hw, y - 4, t, cl(t) + hw, y - 4, 0.2, 0.2); }
    for (let i = 0; i < P.length - 2; i += 2){ const a = P[i], b = P[i + 2]; mb(sd, a, cl(a) - hw, cz(a) - 2.4 + hT(a), b, cl(b) + hw, cz(b) - 2.4 + hT(b), 0.15, 0.15); mb(sd, a, cl(a) + hw, cz(a) - 2.4 + hT(a), b, cl(b) - hw, cz(b) - 2.4 + hT(b), 0.15, 0.15); }
    // floor beams under the deck
