  // towers with the curled (scrolled) tops
  for (const tw of [-TW, TW]){ const yt = liftTower(B, k, cl, dz, tw, hw, 64, col, {sd:cs, depth:8.5, house:4.5, pier:conc});
    for (const sg of [-1, 1]){ const l = cl(tw) + sg*(hw + 0.6), P = []; for (let n = 0; n <= 8; n++){ const a = PI*n/8; P.push([tw - Math.sign(tw)*(4 - 4*Math.cos(a)), yt - 4 + 4*Math.sin(a) + 2]); }
      for (let n = 0; n < 8; n++) mb(st, P[n][0], l, P[n][1], P[n + 1][0], l, P[n + 1][1], 0.5, 0.5); }
    bx(aw, tw - 0.3, tw + 0.3, yt + 0.6, yt + 1.2, cl(tw) - 0.3, cl(tw) + 0.3); lights.push(tw, yt + 1.6, -cl(tw)); }
