  lamps(lp, L1, -600, 600, 50, L1.l(0) > L2.l(0) ? 1 : -1, 9, lamp, 1.2); lamps(lp, L2, -600, 600, 50, L1.l(0) > L2.l(0) ? -1 : 1, 9, lamp, 0.4);
