// --- Roosevelt Island Bridge: 127 m lift span (Warren through truss) between two steel towers, steel girder approaches
function riKey(){
  const k = 'nyribridge', [g, s] = frame(50), B = mkB(), lamp = [], lights = [];
  const L = ln(k, 261390), L0 = ln(k, 353094), LP = ln(k, 354305), dz = t => (t < L.T0 ? L0 : L).z(t), cl = t => (t < L.T0 ? L0 : L).l(t);
  const col = {c:'#5f7f86', lk:0.55}, cs = {c:'#527078', lk:0.4}, conc = {c:'#bbb5aa', lk:0.35};
  const hw = 7.4 + (LP ? 0 : 0), st = B.p(col), sd = B.p(cs), lp = B.p(LAMP), aw = B.p(RED);
  const ta = -19, tb = 108, P = []; for (let n = 0; n <= 12; n++) P.push(ta + (tb - ta)*n/12);
  for (const sg of [-1, 1]) truss(st, P, t => cl(t) + sg*hw, t => dz(t) - 1.6, t => dz(t) + 8.4, 'warren', 0.45, 0.26);
  for (const t of P){ mb(sd, t, cl(t) - hw, dz(t) - 1.9, t, cl(t) + hw, dz(t) - 1.9, 0.22, 0.45); mb(sd, t, cl(t) - hw, dz(t) + 8.4, t, cl(t) + hw, dz(t) + 8.4, 0.2, 0.22); }
  for (let n = 0; n < 12; n += 2){ const a = P[n], b = P[n + 2]; mb(sd, a, cl(a) - hw, dz(a) + 8.4, b, cl(b) + hw, dz(b) + 8.4, 0.1, 0.1); mb(sd, a, cl(a) + hw, dz(a) + 8.4, b, cl(b) - hw, dz(b) + 8.4, 0.1, 0.1); }
  for (const tw of [ta - 4, tb + 4]){ const yt = liftTower(B, k, cl, dz, tw, hw, 46, col, {sd:cs, depth:7, house:5, pier:conc}); bx(aw, tw - 0.3, tw + 0.3, yt + 0.6, yt + 1.2, cl(tw) - 0.3, cl(tw) + 0.3); lights.push(tw, yt + 1.6, -cl(tw)); }
  approach(B, k, L0, L0.T0, L0.T1, cs, conc, 22, 1.5);
  approach(B, k, L, L.T0, ta - 8, cs, conc, 22, 1.5); approach(B, k, L, tb + 8, L.T1, cs, conc, 24, 1.5);
  if (LP){ approach(B, k, LP, LP.T0, ta - 8, cs, conc, 22, 0.8); approach(B, k, LP, tb + 8, LP.T1, cs, conc, 24, 0.8); }
  lamps(lp, L, L.T0 + 4, L.T1 - 4, 32, 1, 8, lamp, 0.3); lamps(lp, L, L.T0 + 4, L.T1 - 4, 32, -1, 8, lamp, 0.3);
  for (let t = DK[k].t0 + 40; t <= DK[k].t1 - 40; t += 25) mark(st, t, cl(t));
  B.flush(s); sprites(s, lamp, [1, 0.85, 0.6], 7); sprites(s, lights, [1, 0.25, 0.15], 8);
  return g;
}
